package in.asmj.ride.web;
import in.asmj.ride.model.*;import in.asmj.ride.repo.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.util.*;
@Controller public class PaymentController {
 private final UserAccountRepository users;private final RideBookingRepository rides;private final PaymentRecordRepository payments;private final FareRuleRepository fares;
 public PaymentController(UserAccountRepository u,RideBookingRepository r,PaymentRecordRepository p,FareRuleRepository f){users=u;rides=r;payments=p;fares=f;}
 private UserAccount me(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 @GetMapping("/payments") public String payments(Authentication a,Model m){UserAccount u=me(a);List<PaymentRecord> list;if("ADMIN".equals(u.getRole()))list=payments.findAllByOrderByCreatedAtDesc();else if("DRIVER".equals(u.getRole()))list=payments.findByDriverIdOrderByCreatedAtDesc(u.getId());else if("FLEET_OWNER".equals(u.getRole()))list=payments.findByFleetOwnerIdOrderByCreatedAtDesc(u.getId());else list=payments.findAllByOrderByCreatedAtDesc().stream().filter(x->u.getId().equals(x.getCustomerId())).toList();m.addAttribute("payments",list);m.addAttribute("role",u.getRole());return "payments";}
 @PostMapping("/payments/ride/{rideId}/submit") public String submit(Authentication a,@PathVariable String rideId,@RequestParam String method,@RequestParam(required=false) String upiReference){UserAccount u=me(a);RideBooking r=rides.findById(rideId).orElseThrow();if(!u.getId().equals(r.getCustomerId())||!"COMPLETED".equals(r.getStatus())||!List.of("CASH","UPI").contains(method)||!method.equals(r.getPaymentMethod()))return "redirect:/customer?paymentError";if("UPI".equals(method)&&(upiReference==null||!upiReference.matches("[A-Za-z0-9@._-]{6,80}")))return "redirect:/customer?paymentError";
 PaymentRecord p=payments.findByRideId(rideId).orElseGet(PaymentRecord::new);if(p.getId()!=null&&!List.of("PAYMENT_REJECTED").contains(p.getStatus()))return "redirect:/payments?alreadySubmitted";p.setRideId(rideId);p.setCustomerId(u.getId());p.setDriverId(r.getAssignedDriverId());UserAccount d=users.findById(r.getAssignedDriverId()).orElse(null);p.setFleetOwnerId(d==null?null:d.getFleetOwnerId());p.setMethod(method);p.setGrossAmount(r.getFinalFare());double rate=d!=null&&d.getFleetOwnerId()!=null?fare().getFleetCommissionPercent():fare().getIndividualCommissionPercent();p.setCommissionRate(rate);p.setCommissionAmount(Math.round(r.getFinalFare()*rate)/100.0);p.setDriverNetAmount(Math.max(0,r.getFinalFare()-p.getCommissionAmount()));p.setUpiReference("UPI".equals(method)?upiReference.trim():null);p.setStatus("CASH".equals(method)?"CASH_TO_COLLECT":"UPI_SUBMITTED");payments.save(p);return "redirect:/payments?submitted";}
 @PostMapping("/payments/{id}/cash-collected") public String cashCollected(Authentication a,@PathVariable String id){UserAccount u=me(a);PaymentRecord p=payments.findById(id).orElseThrow();if(!u.getId().equals(p.getDriverId())||!"CASH".equals(p.getMethod())||!"CASH_TO_COLLECT".equals(p.getStatus()))return "redirect:/payments?error";p.setStatus("PAID");payments.save(p);return "redirect:/payments?updated";}
 @PostMapping("/admin/payments/{id}/verify") public String verify(@PathVariable String id,@RequestParam String decision,@RequestParam(required=false)String note){PaymentRecord p=payments.findById(id).orElseThrow();if("APPROVE".equals(decision)&&"UPI_SUBMITTED".equals(p.getStatus()))p.setStatus("PAID");else if("REJECT".equals(decision)&&"UPI_SUBMITTED".equals(p.getStatus()))p.setStatus("PAYMENT_REJECTED");else if("REFUND".equals(decision)&&"PAID".equals(p.getStatus()))p.setStatus("REFUND_PROCESSED");else return "redirect:/payments?error";p.setAdminNote(note);payments.save(p);return "redirect:/payments?updated";}
 @PostMapping("/admin/payments/{id}/settle") public String settle(@PathVariable String id){PaymentRecord p=payments.findById(id).orElseThrow();if(!"PAID".equals(p.getStatus()))return "redirect:/payments?error";p.setSettled(true);payments.save(p);return "redirect:/payments?settled";}
 private FareRule fare(){return fares.findById("default").orElseGet(()->fares.save(new FareRule()));}
}
